export function Ticker({ step }: { step: number }) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => setCount(count + step), 1000);
    return () => clearInterval(id);
  }, []);

  return <span>{count}</span>;
}

